let frontmatter = {
    "title": "Merge Queue & Manual Merge-Train Runbook"
};
let structuredData = {
    "contents": [
        {
            "heading": "merge-queue--manual-merge-train-runbook",
            "content": "Since v3.8.49 (WS3.2/WS3.4 of the quality/velocity plan) the default merge path for\r\nreviewed PRs into `release/vX.Y.Z` is the **Mergify merge queue** (`.mergify.yml`);\r\nthe **manual merge-train** documented below is the FALLBACK — used during incidents,\r\nrelease freezes, or if the Mergify Open Source plan ever changes."
        },
        {
            "heading": "default-path-the-mergify-queue",
            "content": "PR is reviewed/greened by the campaigns and approved by the owner's pre-merge ⭐\r\ngate (the report + per-item decision — see `/merge-prs` Step 0.75)."
        },
        {
            "heading": "default-path-the-mergify-queue",
            "content": "The owner (or the session acting on the owner's decision) applies the &#x2A;*`queue`**\r\nlabel. The label IS the merge approval; Mergify only executes it."
        },
        {
            "heading": "default-path-the-mergify-queue",
            "content": "Mergify batches up to 10 queued PRs, validates the batch against the fast-gates,\r\nand merges (squash). A red batch is **bisected automatically** — the offending PR\r\nis isolated in \\~log2(N) revalidations and unqueued; the rest proceed."
        },
        {
            "heading": "default-path-the-mergify-queue",
            "content": "Post-merge, the continuous release-green workflow validates the new tip on push\r\nand opens an attribution issue if the combination regressed (never auto-revert)."
        },
        {
            "heading": "default-path-the-mergify-queue",
            "content": "Guardrails (mirror `CLAUDE.md` Hard Rules #21/#22):"
        },
        {
            "heading": "default-path-the-mergify-queue",
            "content": "**Release freeze open** → do NOT label PRs targeting the frozen branch; retarget to\r\nthe active `release/vX+1` first."
        },
        {
            "heading": "default-path-the-mergify-queue",
            "content": "**Another session's in-flight PR** → never label it; only the owning session queues\r\nits own work."
        },
        {
            "heading": "default-path-the-mergify-queue",
            "content": "Tests-only diffs and `hotfix`-labeled PRs already run reduced CI (see\r\n`RELEASE_CHECKLIST.md` → Hotfix Fast-Lane); the queue conditions accept whatever\r\ncheck set actually ran (`#check-failure=0` + `#check-pending=0`)."
        },
        {
            "heading": "fallback-the-manual-merge-train",
            "content": "Used when the queue is unavailable. This codifies the practice that drained 33 PRs in\r\none day during the v3.8.47 cycle:"
        },
        {
            "heading": "fallback-the-manual-merge-train",
            "content": "**Assemble the batch** (\\~10–30 reviewed+approved PRs). Check `linked:` collisions\r\n(same `tap.testFiles`, same CHANGELOG hunks) and serialize those."
        },
        {
            "heading": "fallback-the-manual-merge-train",
            "content": "**Validate ONCE**: in an isolated worktree off the release tip, merge all batch\r\nheads locally, then run the release-equivalent suite\r\n(`npm run check:release-green`, add `--with-build` before a release).\r\n`scripts/release/merge-train.sh <base> <PR#>…` automates steps 1–2 (conflicting\r\nPRs eject, the train continues). Full mode runs `npm run test:unit` — the\r\nbox-tuned runner (`--test-concurrency=20`), **not** the two sequential 4-core CI\r\nshards, which drove the dominant phase at \\~25% of a 16-core box (fixed\r\n2026-07-18). `--fast` (intra-day mega-train drains, owner-approved 2026-07-18)\r\nkeeps every static gate + vitest but runs only the node:test files changed by the\r\nboarded PRs; the FULL suite must still run at least once per day on the\r\naccumulated tip (one train without `--fast`)."
        },
        {
            "heading": "fallback-the-manual-merge-train",
            "content": "**Green** → merge the PRs in sequence (re-checking `state,headRefOid` before each —\r\na PR whose head moved re-enters review). Prove the net diff of each merge is the\r\nPR's own change (no auto-resolve reverts: audit `git diff --stat` for\r\nout-of-scope deletions)."
        },
        {
            "heading": "fallback-the-manual-merge-train",
            "content": "**Red** → bisect the batch by halves (validate each half) instead of re-validating\r\none-by-one; drop the offending PR back to the review queue with the evidence."
        },
        {
            "heading": "fallback-the-manual-merge-train",
            "content": "**Never**: merge during a freeze into the frozen branch; `git stash` anywhere;\r\nblanket-rerun CI hoping a red goes away (rule: a red is information)."
        },
        {
            "heading": "tiering-why-the-queue-is-safe-with-fast-gates-only",
            "content": "**Per PR** (quality.yml fast-gates): TIA-impacted tests + full unit 4-shard +\r\nvitest + lint bag + typecheck + docs/changelog integrity."
        },
        {
            "heading": "tiering-why-the-queue-is-safe-with-fast-gates-only",
            "content": "**Per batch/tip** (continuous release-green): `--quick` HARD gates on every push to\r\nthe release branch; full `--with-build --full-ci` sweeps 3×/day."
        },
        {
            "heading": "tiering-why-the-queue-is-safe-with-fast-gates-only",
            "content": "**Per release** (ci.yml on the release PR): the complete matrix incl. E2E ×9,\r\npackage-artifact + tarball boot-smoke, coverage/ratchets."
        },
        {
            "heading": "tiering-why-the-queue-is-safe-with-fast-gates-only",
            "content": "Nothing is validated less than before — the heavy surface just runs per batch/tip\r\ninstead of per PR, which is what removes the O(N) round-trips."
        }
    ],
    "headings": [
        {
            "id": "merge-queue--manual-merge-train-runbook",
            "content": "Merge Queue & Manual Merge-Train Runbook"
        },
        {
            "id": "default-path-the-mergify-queue",
            "content": "Default path: the Mergify queue"
        },
        {
            "id": "fallback-the-manual-merge-train",
            "content": "Fallback: the manual merge-train"
        },
        {
            "id": "tiering-why-the-queue-is-safe-with-fast-gates-only",
            "content": "Tiering (why the queue is safe with fast-gates only)"
        }
    ]
};
